                    __lz_push(method_blocks, block)
                end
            end
        elseif node.kind == "VariableDecl" then
            if __lz_unwrap_or(node:attr("visibility"), "") == "public" then
                local name = node:child("name")
                local sig = name
                local ty_opt = node:attr("type")
                if __lz_is_some(ty_opt) then
                    sig = (name .. ": ") .. DocGen.type_str(__lz_unwrap(ty_opt))
                end
                __lz_push(prop_blocks, DocGen.decl_block(sig, node:line(), comments))
            end
        elseif node.kind == "ExternDecl" then
            __lz_push(extern_blocks, DocGen.decl_block(DocGen.extern_sig(node), node:line(), comments))
        elseif node.kind == "EnumDecl" then
            local ename = node:child("name")
            local tp = node:child("type_params")
            local header = ename
            if __lz_len(tp) > 0 then
                header = ((header .. "<") .. Text.join(tp, ", ")) .. ">"
            end
            local doc = DocGen.doc_for(node:line(), comments)
            local vblock = ((("**`" .. header) .. "`**") .. nl) .. nl
            if doc ~= "" then
                vblock = ((vblock .. doc) .. nl) .. nl
            end
            for _, v in __lz_each(node:child("variants")) do
                local vname = v:child("name")
                local fields = v:child("fields")
                if __lz_len(fields) == 0 then
                    vblock = (((vblock .. "- `") .. vname) .. "`") .. nl
                else
                    local fstrs = (function() local __lz_m3 = __lz_list() for _, f in __lz_each(fields) do __lz_push(__lz_m3, DocGen.type_str(f)) end return __lz_m3 end)()
                    vblock = (((((vblock .. "- `") .. vname) .. "(") .. Text.join(fstrs, ", ")) .. ")`") .. nl
                end
            end
            __lz_push(variant_blocks, vblock)
        elseif node.kind == "InterfaceDecl" then
            local iname = node:child("name")
            if iname == "" then
                iname = module_name
            end
            local tp = node:child("type_params")
            local header = iname
            if __lz_len(tp) > 0 then
                header = ((header .. "<") .. Text.join(tp, ", ")) .. ">"
            end
            local iblock = ((("**`interface " .. header) .. "`**") .. nl) .. nl
            for _, m in __lz_each(node:child("methods")) do
                local mname = m:child("name")
                local mtp = m:child("type_params")
                local mpt = m:child("param_types")
                local mret = m:child("return_type")
                local msig = mname
                if __lz_len(mtp) > 0 then
                    msig = ((msig .. "<") .. Text.join(mtp, ", ")) .. ">"
                end
                msig = ((msig .. "(") .. Text.join((function() local __lz_m4 = __lz_list() for _, pt in __lz_each(mpt) do __lz_push(__lz_m4, DocGen.type_str(pt)) end return __lz_m4 end)(), ", ")) .. ")"
                if not ((mret.kind == "TypeName") and (mret:child("name") == "dynamic")) then
                    msig = (msig .. ": ") .. DocGen.type_str(mret)
                end
                iblock = (((iblock .. "- `") .. msig) .. "`") .. nl
            end
            for _, p in __lz_each(node:child("properties")) do
                iblock = (((((iblock .. "- `") .. p:child("name")) .. ": ") .. DocGen.type_str(p:child("type"))) .. "`") .. nl
            end
            __lz_push(iface_blocks, iblock)
        end
    end
    out = out .. DocGen.emit_section("Constructor", ctor_blocks)
    out = out .. DocGen.emit_section("Properties", prop_blocks)
    out = out .. DocGen.emit_section("Methods", method_blocks)
    out = out .. DocGen.emit_section("Functions", func_blocks)
    out = out .. DocGen.emit_section("Externs", extern_blocks)
    out = out .. DocGen.emit_section("Variants", variant_blocks)
    out = out .. DocGen.emit_section("Interface", iface_blocks)
    return out
end

return DocGen.new(...)